App.register({group:'workspace',label:'04 / 项目工作区',routes:[{path:'workspace/projects',title:'项目中心',icon:'▣',permission:'workspace',render(){const ps=DB.projects.filter(p=>p.tenant===DB.state.tenant&&(DB.state.identity!=='employee'||p.owner===DB.identities.find(i=>i.role==='employee').user));return UI.page('WORKSPACE / PROJECTS','创作项目中心','项目是短剧生产的主业务对象，承载剧本版本、生产计划、镜头单元、资产与交付。',(DB.state.identity==='auditor'?'' : UI.btn('＋ 新建项目','project:new','btn-primary')),`<div class="grid grid-4">${UI.metric('全部项目',ps.length,'当前租户归属','▣')}${UI.metric('制作中',ps.filter(p=>p.status==='制作中').length,'AI 任务运行中','◌')}${UI.metric('待审核',ps.filter(p=>p.status.includes('审核')).length,'需要人工决策','!')}${UI.metric('已交付',ps.filter(p=>p.status==='已交付').length,'正式交付记录','↗')}</div><div class="card section-gap"><div class="toolbar"><div class="toolbar-left"><b class="small">项目列表</b><select class="field" style="width:auto" id="project-status"><option value="all">全部状态</option><option>制作中</option><option>已交付</option><option>异常待处理</option></select></div><input class="search" data-filter placeholder="搜索项目名称 / 编号"></div>${UI.table(['项目','题材','负责人','集数进度','当前阶段','状态','更新','操作'],ps.map(p=>`<tr data-search="${p.title} ${p.id}"><td><div class="entity"><div class="entity-mark">${p.title.slice(0,1)}</div><div><div class="entity-name">${p.title}</div><div class="entity-meta mono">${p.id}</div></div></div></td><td>${p.genre}</td><td>${p.owner}</td><td><div style="width:90px">${UI.progress(Math.round(p.done/p.episodes*100),p.done+'/'+p.episodes+' 集')}</div></td><td>${p.stage}</td><td>${UI.tag(p.status,p.status==='已交付'?'green':p.status.includes('异常')?'red':p.status.includes('审核')?'orange':'blue')}</td><td class="muted">${p.updated}</td><td><button class="btn btn-sm" data-action="project:open" data-id="${p.id}">档案</button></td></tr>`))}</div>`); }},{path:'workspace/detail',title:'项目档案',icon:'◧',permission:'workspace',render(){const p=DB.projects.find(x=>x.id===DB.state.projectId)||DB.projects[0];return UI.page('WORKSPACE / PROJECT FILE','项目档案 · '+p.title,'统一查看项目主档、正式剧本版本、生产计划、数字资产和最终交付。',UI.btn('进入 AI 创作','go:studio/brief','btn-lime'),`<div class="grid grid-3"><div class="card"><div class="eyebrow">PROJECT ID</div><div class="mono" style="font-size:17px;margin:9px 0">${p.id}</div>${UI.tag(p.status,p.status==='已交付'?'green':'blue')}</div>${UI.metric('计划集数',p.episodes,'当前已完成 '+p.done+' 集','▤')}${UI.metric('累计生产成本','¥'+p.cost.toLocaleString(),'关联模型调用与生产任务','￥')}</div><div class="grid grid-2 section-gap"><div class="card"><div class="card-title">生产链路</div><div class="timeline section-gap">${['创意策划与剧本','人工剧本审核','导演分镜与视觉设计','视频镜头生产','音频与后期合成','AI 质检与人工终审','正式交付与归档'].map((s,i)=>`<div class="timeline-item"><i class="timeline-dot ${i<4?'done':''}"></i><div><div class="timeline-title">${s}</div><div class="timeline-meta">${i===1?'人工审核节点':i===5?'人工最终审核节点':'AI 自动生产 / 系统记录'}</div></div></div>`).join('')}</div></div><div class="card"><div class="card-title">项目追溯关系</div><div class="kpi-line"><span>正式剧本版本</span><b>V3</b></div><div class="kpi-line"><span>镜头生产单元</span><b>96</b></div><div class="kpi-line"><span>视觉 / 音频资产</span><b>18 / 26</b></div><div class="kpi-line"><span>质检综合分</span><b>${p.quality}/100</b></div><div class="kpi-line"><span>归属租户</span><b>${DB.tenants.find(t=>t.id===p.tenant)?.name||'已归档'}</b></div>${UI.btn('查看数字资产','go:assets/library','btn-sm')}</div></div>`);}}]});
